const POKEDEX_GEN_RANGES = [{"gen":1,"label":"Kanto","from":1,"to":151},{"gen":2,"label":"Johto","from":152,"to":251},{"gen":3,"label":"Hoenn","from":252,"to":386},{"gen":4,"label":"Sinnoh","from":387,"to":493},{"gen":5,"label":"Unova","from":494,"to":649},{"gen":6,"label":"Kalos","from":650,"to":721},{"gen":7,"label":"Alola","from":722,"to":809},{"gen":8,"label":"Galar/Hisui","from":810,"to":905},{"gen":9,"label":"Paldea","from":906,"to":1025}];

function dexGenOf(dexNum){
  const r = POKEDEX_GEN_RANGES.find(function(g){ return dexNum >= g.from && dexNum <= g.to; });
  return r ? r.gen : null;
}

// Normalizacao nome de carta -> slug de especie base. Cobre: Mega X/Y,
// ex/EX/GX/V/VMAX/VSTAR/Prime/LEGEND/BREAK/Star, prefixos regionais
// (Alolan/Galarian/Hisuian/Paldean), prefixos de time (Team Rocket's etc.)
// e possessivos de personagem genericos ("N's ", "Ethan's " etc.).
// Paradoxos (Iron Hands, Great Tusk etc.) ja sao o proprio nome de especie —
// nao precisam de regra, so entram no dicionario de excecoes por seguranca.
const PDX_PREFIX_STRIP = [
  'Mega ', "Team Rocket's ", "Team Aqua's ", "Team Magma's ", "Team Skull's ",
  'Alolan ', 'Galarian ', 'Hisuian ', 'Paldean ',
  'Dark ', 'Light ', 'Shining ', 'Radiant ', "Rocket's ",
];
const PDX_SUFFIX_STRIP = [
  ' ex', ' EX', ' GX', ' VMAX', ' VSTAR', ' V-UNION', ' V', ' Prime', ' LEGEND',
  ' BREAK', ' Star', ' \u03b4', ' Tag Team', ' Prism Star', ' SP',
];
const PDX_EXCEPTIONS = {"iron bundle":"iron-bundle","iron hands":"iron-hands","iron treads":"iron-treads","iron jugulis":"iron-jugulis","iron moth":"iron-moth","iron thorns":"iron-thorns","iron leaves":"iron-leaves","iron valiant":"iron-valiant","iron boulder":"iron-boulder","iron crown":"iron-crown","great tusk":"great-tusk","scream tail":"scream-tail","brute bonnet":"brute-bonnet","flutter mane":"flutter-mane","slither wing":"slither-wing","sandy shocks":"sandy-shocks","roaring moon":"roaring-moon","walking wake":"walking-wake","gouging fire":"gouging-fire","raging bolt":"raging-bolt","farfetch'd":"farfetchd","sirfetch'd":"sirfetchd","mr. mime":"mr-mime","mr mime":"mr-mime","mime jr.":"mime-jr","mime jr":"mime-jr","mr. rime":"mr-rime","mr rime":"mr-rime","type: null":"type-null","ho-oh":"ho-oh","jangmo-o":"jangmo-o","hakamo-o":"hakamo-o","kommo-o":"kommo-o","tapu koko":"tapu-koko","tapu lele":"tapu-lele","tapu bulu":"tapu-bulu","tapu fini":"tapu-fini","nidoran f":"nidoran-f","nidoran m":"nidoran-m","nidoran♀":"nidoran-f","nidoran♂":"nidoran-m","flabébé":"flabebe","flabebe":"flabebe","wo-chien":"wo-chien","chien-pao":"chien-pao","ting-lu":"ting-lu","chi-yu":"chi-yu","porygon-z":"porygon-z","porygon2":"porygon2","porygon 2":"porygon2"};

function normalizeCardNameToSpeciesSlug(rawName){
  if(!rawName) return null;
  var n = String(rawName);
  var changed = true;
  while(changed){
    changed = false;
    for(var i=0;i<PDX_SUFFIX_STRIP.length;i++){
      var suf = PDX_SUFFIX_STRIP[i];
      if(n.endsWith(suf)){ n = n.slice(0, -suf.length).trim(); changed = true; }
    }
  }
  n = n.replace(/\s+(X|Y)$/, '');
  for(var j=0;j<PDX_PREFIX_STRIP.length;j++){
    var pre = PDX_PREFIX_STRIP[j];
    if(n.indexOf(pre)===0) n = n.slice(pre.length).trim();
  }
  var possessiveMatch = n.match(/^(.+?)'s\s+(.+)$/);
  if(possessiveMatch && possessiveMatch[2].length > 2) n = possessiveMatch[2];
  var lower = n.toLowerCase().trim();
  if(PDX_EXCEPTIONS[lower]) return PDX_EXCEPTIONS[lower];
  return lower
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[.']/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

// Especie (objeto {dex,slug,name}) a partir de um nome de carta, ou null se
// nao bater com nenhuma das 1025 (normal pra treinador/energia/personagem).
const _PDX_BY_SLUG = {};
POKEDEX_NACIONAL.forEach(function(s){ _PDX_BY_SLUG[s.slug] = s; });
function speciesFromCardName(cardName){
  var slug = normalizeCardNameToSpeciesSlug(cardName);
  return slug ? (_PDX_BY_SLUG[slug] || null) : null;
}
